import hashlib, json, re, sqlite3, sys
from pathlib import Path

TABLES = ('batches','tasks','task_receipts','task_progress','task_progress_receipts','task_progress_extend_receipts','completion_actions','task_attempts')
PREFIX = 'coord_b3_hold_'

def update_sql(name, table, columns):
    condition = ' OR '.join(f'OLD."{column}" IS NOT NEW."{column}"' for column in columns)
    return f'CREATE TRIGGER "{name}" BEFORE UPDATE ON "{table}" WHEN {condition} BEGIN SELECT RAISE(ABORT,\'coord_b3_business_frozen\'); END'

def statements(db):
    existing = {r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
    result = {}
    for table in TABLES:
        if table not in existing:
            if table == 'task_attempts':
                continue  # Candidate creates this derived table additively during its first open.
            raise ValueError('Required business table missing: '+table)
        for operation in ('INSERT','UPDATE','DELETE'):
            name = PREFIX+table+'_'+operation.lower()
            if operation == 'UPDATE':
                columns = [row[1] for row in db.execute('PRAGMA table_info("'+table+'")')]
                result[name] = update_sql(name,table,columns)
                continue
            condition = ''
            if table == 'task_attempts' and operation == 'INSERT':
                # Candidate replays INSERT OR IGNORE for existing derived PKs on every open.
                condition = ' WHEN NOT EXISTS (SELECT 1 FROM task_attempts WHERE task_id=NEW.task_id AND attempt_no=NEW.attempt_no)'
            result[name] = f'CREATE TRIGGER "{name}" BEFORE {operation} ON "{table}"{condition} BEGIN SELECT RAISE(ABORT,\'coord_b3_business_frozen\'); END'
    return result

def install(path, upgrade=False):
    db = sqlite3.connect(path, timeout=5)
    with db:
        db.execute('BEGIN IMMEDIATE')
        expected = statements(db)
        for name, sql in expected.items():
            present = db.execute("SELECT sql FROM sqlite_master WHERE type='trigger' AND name=?",(name,)).fetchone()
            if present and present[0] != sql:
                table = name[len(PREFIX):-len('_update')] if name.endswith('_update') else ''
                previous_columns = re.findall(r'OLD\."([a-zA-Z_][a-zA-Z0-9_]*)" IS NOT NEW\."\1"',present[0])
                current_columns = [row[1] for row in db.execute('PRAGMA table_info("'+table+'")')] if table in TABLES else []
                if not upgrade or not previous_columns or current_columns[:len(previous_columns)] != previous_columns or present[0] != update_sql(name,table,previous_columns):
                    raise ValueError('Existing trigger differs: '+name)
                db.execute('DROP TRIGGER "'+name+'"')
                present = None
            if not present:
                db.execute(sql)
    return dict(state='PASS',triggers=sorted(expected),trigger_count=len(expected),sql_sha256=hashlib.sha256(json.dumps(expected,sort_keys=True).encode()).hexdigest(),upgrade_after_additive_migration=upgrade,policy='Existing-column values immutable; no-op updates allowed. New migration columns are initialized before atomic upgrade covers all columns. Business INSERT/DELETE blocked; agents/nonces remain available; existing derived INSERT OR IGNORE rows allowed on restart')

def snapshot(db):
    output = {}
    for table in TABLES:
        if db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",(table,)).fetchone():
            columns = [r[1] for r in db.execute('PRAGMA table_info("'+table+'")')]
            rows = list(db.execute('SELECT * FROM "'+table+'"'))
            output[table] = dict(columns=columns,rows=sorted(rows,key=repr))
    return output

def verify_denials(path):
    db = sqlite3.connect(path,timeout=5)
    before = snapshot(db)
    denied = []
    for table, sql in [('tasks',"UPDATE tasks SET state='pending'"),('batches',"UPDATE batches SET status=CASE WHEN status='active' THEN 'cancelled' ELSE 'active' END"),('task_receipts',"DELETE FROM task_receipts"),('completion_actions',"UPDATE completion_actions SET state='pending'")]:
        try:
            with db:
                db.execute(sql)
            raise ValueError('Write unexpectedly accepted: '+table)
        except sqlite3.IntegrityError as error:
            if str(error) != 'coord_b3_business_frozen':
                raise
            denied.append(table)
    after = snapshot(db)
    if before != after:
        raise ValueError('Business rows changed')
    return dict(state='PASS',denied=denied,all_business_rows_equal=True)

def prepare_isolated(path):
    db = sqlite3.connect(path)
    with db:
        held = db.execute("UPDATE tasks SET lease_until='2000-01-01T00:00:00Z' WHERE name IN ('owned-frozen-reclaim','owned-frozen-pending') AND state='claimed'").rowcount
        action = db.execute("UPDATE completion_actions SET state='pending' WHERE id=(SELECT id FROM completion_actions WHERE action_kind='on_task_completed' ORDER BY id LIMIT 1)").rowcount
        if held != 1 or action != 1:
            raise ValueError('Expected only the owned synthetic reclaim/action probes')
    target = Path(path).with_name('frozen-before.private.db')
    if target.exists():
        raise ValueError('Isolated reference copy already exists')
    with sqlite3.connect(target) as reference:
        db.backup(reference)
    batch = db.execute("SELECT batch_id FROM tasks WHERE name IN ('owned-frozen-reclaim','owned-frozen-pending') AND state='claimed'").fetchone()[0]
    return dict(state='PASS',owned_expired_claims=held,owned_pending_actions=action,owned_batch_id=batch)

def compare_isolated(path):
    with sqlite3.connect(path) as db, sqlite3.connect(Path(path).with_name('frozen-before.private.db')) as reference:
        if snapshot(db) != snapshot(reference):
            raise ValueError('Frozen business rows differ from isolated reference')
    return dict(state='PASS',full_business_rows_equal=True,comparison='All columns including fences compared privately; no credential values or derived hashes emitted')

def remove_isolated(path):
    db = sqlite3.connect(path)
    before = snapshot(db)
    with db:
        expected = statements(db)
        for name, sql in expected.items():
            row = db.execute("SELECT sql FROM sqlite_master WHERE type='trigger' AND name=?",(name,)).fetchone()
            if not row or row[0] != sql:
                raise ValueError('Guard no longer matches reviewed isolated definition')
            db.execute('DROP TRIGGER "'+name+'"')
    if before != snapshot(db):
        raise ValueError('Removing isolated guards changed business rows')
    return dict(state='PASS',removed=len(expected),business_rows_unchanged=True)

if __name__ == '__main__':
    operation, path = sys.argv[1:]
    resolved = str(Path(path).resolve())
    allowed = [r'C:\ProgramData\coord\data\coord.db',r'C:\coord-b3a2-20261027-a\publisher\data\fixture.db',r'C:\coord-b3a2-20261027-a\freeze-legacy-v2.private.db']
    if resolved.lower() not in [value.lower() for value in allowed]:
        raise ValueError('Not an exact authorized database path')
    if operation == 'install':
        print(json.dumps(install(path)))
    elif operation == 'upgrade-after-migration':
        print(json.dumps(install(path,upgrade=True)))
    elif operation == 'verify-isolated-denials' and 'coord-b3a2-20261027-a' in resolved:
        print(json.dumps(verify_denials(path)))
    elif operation in ('prepare-isolated','compare-isolated','remove-isolated') and 'coord-b3a2-20261027-a' in resolved:
        print(json.dumps({'prepare-isolated':prepare_isolated,'compare-isolated':compare_isolated,'remove-isolated':remove_isolated}[operation](path)))
    else:
        raise ValueError('Unsupported operation; no production mutation probes or automatic unfreeze')
